import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.CsFjlSKj.js";const k=JSON.parse('{"title":"awk (Data Extraction and Reporting)","description":"","frontmatter":{},"headers":[],"relativePath":"shell/awk.md","filePath":"shell/awk.md"}'),n={name:"shell/awk.md"};function l(h,a,o,p,d,r){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="awk-data-extraction-and-reporting" tabindex="-1"><code>awk</code> (Data Extraction and Reporting) <a class="header-anchor" href="#awk-data-extraction-and-reporting" aria-label="Permalink to &quot;\`awk\` (Data Extraction and Reporting)&quot;">​</a></h1><p>While <code>grep</code> filters lines and <code>sed</code> transforms them, <code>awk</code> is a complete programming language designed specifically for extracting, calculating, and reporting data from text files (especially columns/tabular data).</p><h2 id="the-awk-execution-model" tabindex="-1">The <code>awk</code> Execution Model <a class="header-anchor" href="#the-awk-execution-model" aria-label="Permalink to &quot;The \`awk\` Execution Model&quot;">​</a></h2><p>An <code>awk</code> program consists of a sequence of <code>pattern { action }</code> statements.</p><ol><li><code>BEGIN { ... }</code>: Executed exactly once <em>before</em> any input is read. Used for setup (e.g., printing headers).</li><li><code>pattern { ... }</code>: Executed for every line that matches the pattern. If no pattern is provided, it executes for <em>every</em> line.</li><li><code>END { ... }</code>: Executed exactly once <em>after</em> all input has been read. Used for summaries (e.g., printing totals).</li></ol><h2 id="fields-and-variables" tabindex="-1">Fields and Variables <a class="header-anchor" href="#fields-and-variables" aria-label="Permalink to &quot;Fields and Variables&quot;">​</a></h2><p>By default, <code>awk</code> splits each line into &quot;fields&quot; (columns) using whitespace (spaces or tabs) as the delimiter.</p><ul><li><code>$0</code>: The entire current line.</li><li><code>$1, $2, $3...</code>: The first, second, third field, etc.</li><li><code>NF</code> (Number of Fields): The total number of fields on the current line. Therefore, <code>$NF</code> represents the <em>last</em> field on the line.</li><li><code>NR</code> (Number of Records): The current line number being processed.</li></ul><h3 id="basic-field-extraction" tabindex="-1">Basic Field Extraction <a class="header-anchor" href="#basic-field-extraction" aria-label="Permalink to &quot;Basic Field Extraction&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Print only the 1st and 3rd columns from a file</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Alice 25 Engineer\\nBob 30 Manager&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $1, $3}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Alice Engineer</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bob Manager</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Print the line number (NR) and the last column ($NF)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print NR, $NF}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.txt</span></span></code></pre></div><h3 id="changing-the-delimiter-f" tabindex="-1">Changing the Delimiter (<code>-F</code>) <a class="header-anchor" href="#changing-the-delimiter-f" aria-label="Permalink to &quot;Changing the Delimiter (\`-F\`)&quot;">​</a></h3><p>If your data is separated by commas (CSV) or colons (like <code>/etc/passwd</code>), use the <code>-F</code> flag.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extract only the usernames (1st column) from the passwd file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;:&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $1}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/passwd</span></span></code></pre></div><h2 id="pattern-matching-and-conditionals" tabindex="-1">Pattern Matching and Conditionals <a class="header-anchor" href="#pattern-matching-and-conditionals" aria-label="Permalink to &quot;Pattern Matching and Conditionals&quot;">​</a></h2><p>You can use standard mathematical and string comparisons in <code>awk</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only print the line if the 2nd column is greater than 50</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;$2 &gt; 50 {print $0}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scores.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only print if the 1st column exactly matches &quot;Alice&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;$1 == &quot;Alice&quot; {print $2}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Regex matching: Print if the 3rd column starts with &quot;E&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;$3 ~ /^E/ {print $0}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.txt</span></span></code></pre></div><h2 id="math-and-aggregation" tabindex="-1">Math and Aggregation <a class="header-anchor" href="#math-and-aggregation" aria-label="Permalink to &quot;Math and Aggregation&quot;">​</a></h2><p>Because <code>awk</code> is a programming language, it excels at calculating totals across columns. Variables in <code>awk</code> do not need to be declared; they default to <code>0</code> or <code>&quot;&quot;</code> (empty string).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Assume a file &#39;sales.txt&#39; has amounts in column 3.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Sum column 3 for all lines, then print the total at the END.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{ total += $3 } END { print &quot;Total Sales: $&quot; total }&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sales.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Calculate the average</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{ total += $3 } END { print &quot;Average: &quot; total/NR }&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sales.txt</span></span></code></pre></div><h2 id="formatted-output-printf" tabindex="-1">Formatted Output (<code>printf</code>) <a class="header-anchor" href="#formatted-output-printf" aria-label="Permalink to &quot;Formatted Output (\`printf\`)&quot;">​</a></h2><p><code>awk</code> uses C-style <code>printf</code> for highly formatted output, allowing you to pad columns and control decimal places.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Format the 2nd column as a float with 2 decimal places</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Alice 45.1234&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{printf &quot;Name: %-10s | Score: %.2f\\n&quot;, $1, $2}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: Name: Alice      | Score: 45.12</span></span></code></pre></div>`,22)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
